import {startRecording} from './recorder.js';
export function createVoiceInput({button,cancelButton,status,input,apiBase,onNotice,canRecord}){
 let phase='idle',recording=null,controller=null,generation=0,timer=null,started=0;
 function render(){button.textContent=phase==='recording'?'结束录音':phase==='transcribing'?'转写中…':'语音';button.setAttribute('aria-pressed',String(phase==='recording'));cancelButton.hidden=phase==='idle';input.readOnly=phase!=='idle';status.textContent=phase==='recording'?'正在录音 '+Math.floor((Date.now()-started)/1000)+' 秒':phase==='transcribing'?'正在识别…':'';}
 function cancel(){generation++;recording?.cancel();recording=null;controller?.abort();controller=null;clearInterval(timer);timer=null;phase='idle';render();}
 async function finish(){const current=recording,stamp=generation;recording=null;clearInterval(timer);timer=null;if(!current)return cancel();phase='transcribing';render();try{const audio=await current.stop();if(stamp!==generation||!audio)return;controller=new AbortController();const response=await fetch(apiBase+'/api/speech/transcribe',{method:'POST',credentials:'include',headers:{'Content-Type':'audio/wav'},body:audio,signal:controller.signal});const data=await response.json();if(!response.ok)throw Error(data.error||'识别失败');if(stamp!==generation)return;const next=[input.value.trim(),data.text].filter(Boolean).join(' ');if(next.length>input.maxLength)throw Error('识别文字与草稿合计超过输入上限');input.value=next;input.dispatchEvent(new Event('input',{bubbles:true}));if(!data.text)onNotice('没有识别到语音');}catch(error){if(stamp===generation&&error.name!=='AbortError')onNotice(error.message);}finally{current.cancel();if(stamp===generation)cancel();}}
 button.onclick=async()=>{if(phase==='recording')return finish();if(phase==='transcribing')return cancel();if(!canRecord())return onNotice('请先登录，禁言期间不能使用语音输入');if(!window.isSecureContext||!navigator.mediaDevices?.getUserMedia)return onNotice('语音输入需要 HTTPS 和麦克风权限');const stamp=++generation;phase='recording';started=Date.now();render();try{const next=await startRecording(()=>void finish());if(stamp!==generation){next.cancel();return;}recording=next;timer=setInterval(()=>{render();if(Date.now()-started>=120000)void finish();},500);}catch(error){if(stamp===generation){cancel();onNotice(error.name==='NotAllowedError'?'请允许使用麦克风':'无法使用麦克风');}}};
 cancelButton.onclick=cancel;document.addEventListener('visibilitychange',()=>{if(document.hidden)cancel();});window.addEventListener('pagehide',cancel);render();return {cancel,get busy(){return phase!=='idle';}};
}
